// probes.server.ts — ask AI answer engines about the brand and its topics,
// then read the answers for mentions and citations of the scanned site.
//
// Paid: every probe is a model call through the OpenRouter gateway, so it is
// metered against the workspace budget, cached (the same question within six
// hours is not re-billed) and only runs when FEATURE_FLAG_GEO_AI_PROBES_ENABLED
// allows it for the workspace. The questions are generated by Mellox, never
// taken from page content, so crawled text cannot steer the model.
import "server-only";
import { chatCompletion } from "@/lib/ai-gateway.server";
import { BudgetExceededError } from "@/server/ai/budget";
import { geoProbeModels } from "@/server/ai/task-models";
import {
  buildProbeQueries,
  detectMentions,
  extractCitations,
  summarizeProbes,
  type ProbeAnswer,
  type ProbeSummary,
} from "@/lib/geo/probes";
import type { ProbeContext } from "./scan-runner.server";
import type { ScanRow } from "./store.server";

const ENGINE_NAMES: Record<string, string> = {
  perplexity: "Perplexity",
  openai: "ChatGPT",
  google: "Gemini",
  anthropic: "Claude",
  "x-ai": "Grok",
};

/** Each engine is asked separately — these are not a fallback chain. */
function probeModels(): string[] {
  return geoProbeModels().slice(0, 4);
}

function maxQueries(): number {
  const n = Number(process.env.GEO_PROBE_MAX_QUERIES);
  return Number.isFinite(n) && n > 0 ? Math.min(10, Math.floor(n)) : 4;
}

const SYSTEM =
  "Answer the question the way you would for someone searching the web. Be concise and specific. " +
  "Name the companies, products or websites you would recommend, and include source URLs where you can.";

function providerCitations(json: unknown): string[] {
  const j = json as {
    citations?: unknown;
    choices?: { message?: { annotations?: { url_citation?: { url?: string } }[] } }[];
  };
  const out: string[] = [];
  if (Array.isArray(j?.citations))
    for (const c of j.citations) if (typeof c === "string") out.push(c);
  for (const a of j?.choices?.[0]?.message?.annotations ?? []) {
    if (typeof a?.url_citation?.url === "string") out.push(a.url_citation.url);
  }
  return out;
}

export async function runGeoProbes(scan: ScanRow, ctx: ProbeContext): Promise<ProbeSummary> {
  const queries = buildProbeQueries({
    brandName: ctx.brandName,
    topics: ctx.topics,
    max: maxQueries(),
  });
  const results: ProbeAnswer[] = [];
  const target = { brandName: ctx.brandName, domain: ctx.site.host };

  outer: for (const model of probeModels()) {
    const engine = ENGINE_NAMES[model.split("/")[0]] ?? model;
    for (const query of queries) {
      try {
        const json = await chatCompletion({
          // One specific engine per probe: its own model, no fallback.
          plan: { models: [model] },
          messages: [
            { role: "system", content: SYSTEM },
            { role: "user", content: query.text },
          ],
          max_tokens: 700,
          temperature: 0.2,
          cacheTtlMs: 6 * 60 * 60 * 1000,
          route: "geo.probe",
          task: "generate",
        });
        const text = String(json?.choices?.[0]?.message?.content ?? "");
        const mentions = detectMentions(text, target);
        const citations = extractCitations(text, providerCitations(json), ctx.site.host);
        results.push({
          query,
          engine,
          model: String(json?._model ?? model),
          status: "ok",
          mentioned: mentions.length > 0,
          cited: citations.some((c) => c.isTarget),
          mentions: mentions.slice(0, 5),
          citations: citations.slice(0, 15),
          excerpt: text.slice(0, 600),
        });
      } catch (error) {
        results.push({
          query,
          engine,
          model,
          status: "error",
          error: error instanceof Error ? error.message.slice(0, 200) : "Probe failed",
          mentioned: false,
          cited: false,
          mentions: [],
          citations: [],
          excerpt: "",
        });
        // Out of budget: stop spending on this scan, keep what was collected.
        if (error instanceof BudgetExceededError) break outer;
      }
    }
  }
  void scan;
  return summarizeProbes(results, queries.length);
}
